--  Dữ liệu mẫu: chi_so_tran_dau (box score từng cầu thủ cho 37 trận đã đấu mùa 2025-26 + 110 trận thật 2 mùa cũ, file 04)
--  Import SAU 04_du_lieu_tran_dau.sql (cần có cau_thu, tran_dau, doi_bong).
--  Mã cầu thủ theo quy ước trong 03_du_lieu_cau_thu.sql: đội ma_doi = N có cầu thủ
--  (N-1)*8+1 .. N*8, 5 người đầu là đội hình xuất phát.
--  PHẦN 1 (mùa 2025-26): mỗi đội 8 cầu thủ/trận. Mỗi trận: tổng điểm cầu thủ mỗi đội = tỉ số đội trong tran_dau,
--  điểm cá nhân = 2*FG + 3P + FT (đúng ràng buộc CHECK), tổng phút mỗi đội = 240 (+25 mỗi hiệp phụ).
--  LƯU Ý: chỉ số là DỮ LIỆU MẪU TỰ SINH để test, không phải số liệu thật của NBA.
--  Bảng loat_playoff chưa có dữ liệu mẫu vì file 04 chưa có trận playoff:
--  tạo các loạt bằng trang admin/playoff/index.php.
-- =====================================================================
